import { coerceArray } from '@angular/cdk/coercion';
import { BehaviorSubject, combineLatest, from, merge, noop, Observable, of, throwError } from 'rxjs';
import { catchError, filter, map, mapTo, mergeMap, pluck, startWith, switchMap, take, tap } from 'rxjs/operators';
import { Buffer } from 'buffer';
import { ethers } from 'ethers';
import { Injectable, NgZone } from '@angular/core';
import { Network } from '@ethersproject/networks';
import { JsonRpcProvider, JsonRpcSigner } from '@ethersproject/providers/src.ts/json-rpc-provider';

import { ContractService } from '../../contract';
import { Environment } from '@environments/environment.definitions';
import ethereum from '../../../utils/ethereum-types';
import createMetaMaskProvider from 'metamask-extension-provider'
import {METAMASK_LINK, NetworkService} from '../networks.definitions';
import {MetaMaskInpageProvider} from "@metamask/providers";
import Eth from "@metamask/ethjs";

@Injectable()
export class MetamaskService implements NetworkService {
  private signer: BehaviorSubject<JsonRpcSigner> = new BehaviorSubject(null);
  private provider: BehaviorSubject<JsonRpcProvider> = new BehaviorSubject(null);
  private isConnectingSbj: BehaviorSubject<boolean> = new BehaviorSubject(false);
  private pr: MetaMaskInpageProvider
  private web3

    constructor(
    private contractService: ContractService,
    private environment: Environment,
    private ngZone: NgZone,
  ) {
      // console.log('METAMASK SERVICE: ', this.pr)
    if (!this.isAPIAvailable()) {
      return;
    }

    combineLatest([
      this.getWalletAddress(),
      this.getChainId(),
    ]).subscribe(([account]) => {
      console.log('account: ', account)
      this.provider.next(account && new ethers.providers.Web3Provider(ethereum));
      this.signer.next(account && this.provider.value.getSigner());
    });
  }

  public checkActiveNetworkAllowed(allowedChainId: number | number[]): Observable<boolean> {
    return this.getChainId().pipe(
      map((chainId) => coerceArray(allowedChainId).includes(+chainId)),
    );
  }

  public isAPIAvailable(): boolean {
      // console.log('prprprrpp');
      // console.log('metamsk: ', this.pr._metamask);;
       return !!ethereum;
  }

  public isConnecting(): Observable<boolean> {
    return this.isConnectingSbj;
  }

  public connect(): Promise<boolean> {
    if (!this.isAPIAvailable()) {
      window.open(METAMASK_LINK, '_blank');
      return Promise.resolve(false);
    }

    this.isConnectingSbj.next(true);

    return this.checkActiveNetworkAllowed(this.environment.metamaskAllowedChainIds).pipe(
      take(1),
      switchMap((isChainIdAllowed) => {
        if (!isChainIdAllowed) {
          return throwError(new Error('Please select Mainnet network in MetaMask'));
        }

        return ethereum.request<boolean>({ method: 'eth_requestAccounts' });
      }),
      switchMap(() => this.addToken()),
      catchError((error) => {
        this.isConnectingSbj.next(false);

        switch (error.code) {
          // EIP-1193 userRejectedRequest error
          case 4001: {
            return throwError(new Error('Please connect to MetaMask'));
          }
          case -32002: {
            return throwError(new Error('Already trying to connect'));
          }
          default: {
            return throwError(new Error(error.message));
          }
        }
      }),
      tap(() => this.isConnectingSbj.next(false)),
    ).toPromise();
  }

  public addToken(): Promise<boolean> {
    return this.contractService.getContractData().pipe(
      switchMap((contractData) => ethereum.request<boolean>({
        method: 'wallet_watchAsset',
        params: {
          type: 'ERC20',
          options: {
            ...contractData,
          },
        },
      })),
    ).toPromise();
  }

  public isConnected(): Observable<boolean> {
    if (!this.isAPIAvailable()) {
      return of(false);
    }

    return combineLatest([
      this.checkActiveNetworkAllowed(this.environment.metamaskAllowedChainIds),
      this.getWalletAddress().pipe(
        map((account) => !!account),
      ),
    ]).pipe(
      map((conditions) => conditions.every(Boolean)),
    );
  }

  public getWalletAddress(): Observable<string> {
    return from(createMetaMaskProvider().request({ method: 'eth_accounts' })).pipe(
      tap((accounts) => console.log('accounts: ', accounts)),
      mergeMap((accounts: string[]) => this.listenEthereumEvent<string[]>('accountsChanged').pipe(
        startWith(accounts),
      )),
      pluck(0),
    );
  }

  public getBalance(): Observable<string> {
    return this.signer.pipe(
      filter((signer) => !!signer),
      switchMap((signer) => signer.getAddress()),
      switchMap((address) => this.contractService.getBalance(address)),
      map(ethers.utils.formatEther),
      catchError(() => of('0')),
    );
  }

  public getChainId(): Observable<number> {
    const provider = new ethers.providers.Web3Provider(ethereum);

    return from(provider.detectNetwork()).pipe(
      pluck('chainId'),
      mergeMap((chainId: number) => this.listenEthereumEvent<number>('chainChanged').pipe(
        startWith(chainId),
      )),
    );
  }

  public getConnected(): Observable<boolean> {
    return this.getWalletAddress().pipe(
      switchMap((account) => {
        return merge(
          this.listenEthereumEvent('connect').pipe(
            mapTo(true),
          ),
          this.listenEthereumEvent('disconnect').pipe(
            mapTo(false),
          ),
        ).pipe(
          startWith(!!account),
        );
      }),
    );
  }

  public getNetwork(): Observable<Network> {
    return this.provider.pipe(
      switchMap((provider) => provider ? provider.detectNetwork() : of(undefined)),
    );
  }

  public getProvider(): Observable<JsonRpcProvider> {
    return this.provider.pipe(
      filter((provider) => !!provider),
    );
  }

  private listenEthereumEvent<T>(eventName: string): Observable<T> {
    return new Observable((subscriber) => {
      const listener = (event: T) => subscriber.next(event);
      ethereum.on(eventName, listener);

      return noop;
    });
  }

  public transferCoin(addressTo: string, amountFrom: string): Promise<string> {
    const contract = this.contractService.getContractInstant();

    return contract.transfer(
      'this.environment.decentrEscrowAddress',
      ethers.utils.parseEther(amountFrom),
    ).then(({ hash }) => hash);
  }

  public signSwap(receiverAddress: string, txHash: string): Promise<string> {
    const message = {
      receiverAddress,
      txHash,
    };

    const messageHex = `0x${Buffer.from(JSON.stringify(message), 'utf8').toString('hex')}`;

    // @ts-ignore
    return this.getWalletAddress().pipe(
      take(1),
      mergeMap((account) => ethereum.request<string>({
          method: 'personal_sign',
          params: [messageHex, account],
        }).then((signature) => signature),
      ),
    ).toPromise();
  }
}
